document.addEventListener("click",(function(t){const e=t.target.closest(".rippled");if(!e)return;const n=document.createElement("span");n.className="ripple",e.appendChild(n);const i=e.getBoundingClientRect(),c=Math.max(i.width,i.height);n.style.width=n.style.height=c+"px";const l=t.clientX-i.left-c/2,s=t.clientY-i.top-c/2;n.style.left=l+"px",n.style.top=s+"px",n.addEventListener("animationend",(function(){n.remove()}))}));